def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict = {k: v for k, v in chain_dict.items() if v}

    result = []
    current = chain_dict.get(chain[0], None)

    while current is not None:
        result.append(current)
        next_item = current[0]
        current = chain_dict.get(current[0], None)

    return result[::-1]

# Example usage:
# print(chain_follow((('a', 'b'), ('b', 'c'), ('c', 'd'))))
